// INGESTION + NORMALIZATION: schedule / webhook / telegram -> Event schema chung.
const raw = $input.first().json;
const body = raw.body || {};
const now = new Date();
const p = (n) => String(n).padStart(2, '0');
const stamp = `${now.getFullYear()}${p(now.getMonth() + 1)}${p(now.getDate())}_${p(now.getHours())}${p(now.getMinutes())}`;
const uid = Math.random().toString(36).slice(2, 8);
let event;
if (raw.chat) {
  event = { type: 'telegram_chat', entity: String((raw.chat && raw.chat.id) || 'unknown'), payload: { text: raw.text || '', chat_id: (raw.chat && raw.chat.id) || null, from: (raw.from && raw.from.username) || '', source: 'telegram' } };
} else if (raw.body) {
  event = { type: body.type || 'business_event', entity: body.entity || 'unknown', payload: body.payload || {} };
} else {
  event = { type: 'inventory_check', entity: 'product_A', payload: { stock: 15, avg_daily_sales: 8 } };
}
// TODO: thay payload demo bang node Fetch (Sheets/ERP/CRM) truoc Normalize.
const prefix = event.payload && event.payload.source === 'telegram' ? 'tg' : 'run';
return [{ json: {
  correlation_id: body.correlation_id || `${prefix}_${stamp}_${uid}`,
  event,
  context: { history_window_days: 30, requested_by: 'dailyops-unified' }
}}];

// Gop DecideResponse + Event goc (giu chat_id/source) — khong reasoning, chi gop du lieu.
const norm = $('Normalize Event').first().json;
const d = $input.first().json;
return [{ json: { ...d, event: norm.event } }];

// REPORT branch: chuan bi dong bao cao cho Google Sheets.
const d = $input.first().json;
return [{ json: { date: new Date().toISOString(), summary: d.decision.summary, confidence: d.decision.confidence, correlation_id: d.correlation_id } }];

// TICKET-specific check: ticket_id co ton tai trong output INSERT khong?
const rows = $input.all().map((i) => i.json);
const agent = $('Route by action_type').first().json;
const ticketId = (rows[0] && rows[0].ticket_id) || null;
const ok = Boolean(ticketId);
return [{ json: { correlation_id: agent.correlation_id, action_type: agent.action_type, ticket_id: ticketId, ticket_ok: ok, ...(ok ? {} : { error: 'Create Ticket returned no ticket_id' }) } }];

// Tao link approve/reject cho human. Nhanh ket thuc o day; resume qua Approval Decision webhook.
const d = $input.first().json;
const base = 'http://localhost:5678/webhook/dailyops-approval';
const q = `correlation_id=${d.correlation_id}`;
return [{ json: { correlation_id: d.correlation_id, action: d.recommended_action, approval_links: { approve: `${base}?${q}&decision=approve`, reject: `${base}?${q}&decision=reject` } } }];

// Resume sau approval: lay lai action da duoc human duyet (tu approvals row).
const r = $input.first().json;
return [{ json: { correlation_id: r.correlation_id, recommended_action: r.requested_action } }];

// Failure outcome (verified=false) + audit row. Khong phu thuoc notify.
const f = $input.first().json;
const action = f.action_type || (f.requested_action ? 'EXECUTE' : 'UNKNOWN');
return [{ json: { correlation_id: f.correlation_id || 'unknown', action_type: action, actor: 'n8n', event: 'system.workflow_failed', verified: false, error: f.error || JSON.stringify(f).slice(0, 500), timestamp: new Date().toISOString() } }];

// STUB: chua retry action-level trong phase nay. Chinh sach: fail -> escalate, khong tu retry ghi.
const f = $input.first().json;
return [{ json: { ...f, retry_policy: 'no_auto_retry_in_this_phase', escalated: true } }];

// Escalation stub: chuan bi thong bao cho human.
const f = $input.first().json;
return [{ json: { ...f, escalation: { channel: 'telegram', text: `[ESCALATION] ${f.correlation_id}: ${f.error}` } } }];

const sup = $('Attach Channel Context').first().json;
function get(n){ try { return $(n).first().json; } catch(e){ return null; } }
const parts = ['Specialist — Business Analyst','Specialist — Knowledge Agent','Specialist — Operations Agent','Specialist — Report Agent'].map(get).filter(Boolean);
const evidence = [];
const errs = [];
parts.forEach((p) => { if (p.error) { errs.push((p.agent || 'unknown') + ': ' + String(p.error).slice(0, 200)); return; } (p.evidence || []).forEach((e) => evidence.push({ source: (p.agent || '?') + ':' + (e.source || ''), content: String(e.content || '').slice(0, 300), score: e.score || 0 })); });
(sup.evidence || []).forEach((e) => evidence.push(e));
const used = parts.map((p) => p.agent).filter(Boolean);
const specialists_used = Array.from(new Set([...(sup.specialists_used || []), ...used]));
return [{ json: { ...sup, specialists_used, evidence, specialist_errors: errs, aggregated_at: new Date().toISOString() } }];

const d = $input.first().json;
const ra = String(d.recommended_action || '').toLowerCase();
const deny = /delete|drop|truncate|shutdown|destroy|rm -rf/.test(ra);
let verdict = 'ALLOW';
if (deny) verdict = 'DENY';
else if (d.needs_approval) verdict = 'APPROVAL';
if (verdict === 'DENY') return [{ json: { ...d, action_type: 'UNKNOWN', policy_verdict: verdict, error: 'Policy DENY: destructive action blocked' } }];
return [{ json: { ...d, policy_verdict: verdict } }];

const agent = $('Route by action_type').first().json;
const out = $input.first().json;
const ok = !out.error && out.success !== false;
if (!ok) throw new Error(out.error || 'execute verification failed');
return [{ json: { correlation_id: agent.correlation_id || 'unknown', action_type: 'EXECUTE', verified: true } }];
